import XCTest
@testable import G2DigestKit

/// The Worker's GET /api/editions/<date> shape. 0.4.1 expected `audio` as {slug: {glance, deep_dive}}
/// while the Worker sends {"<date>/<file>": "<signed url>"}, so every real edition failed to decode.
final class EditionResponseTests: XCTestCase {
    func testWorkerEditionWithSignedAudioDecodes() throws {
        let json = #"""
        {"date":"2026-10-22","title":"Afternoon brief","published_at":"2026-11-10T15:55:13.163+00:00","guide_version":"0.4","brief_version":1,"bundle":{"cut":[],"date":"2026-10-22","cards":[{"body":"Quiet on providers, two research results.","kind":"cover","slug":"cover","title":"Afternoon brief"},{"body":"Designed proteins stick on the first try far more often.","kind":"tldr","slug":"tldr","title":"Protein binders hit 41%","glance":{"script":"If you only hear one thing today: a protein design model is getting working binders on the first try much more often than before. The deep dive on the research card explains why that matters for drug discovery.","audio_path":"2026-10-22/tldr-glance.mp3","duration_sec":11.3},"key_number":"41%"}],"edition":{"intro":"Development fixture: a synthetic edition in the shape of a real one, built against the seeded example brief. None of it is news.","title":"Afternoon brief","sections":[{"body":"Neither tracked company had launches, outages, funding or leadership news in the last day.","title":"Providers","sources":[],"section_id":"providers"},{"body":"RFD4-Proteina, a protein design model, reports that 41% of its lab-tested designs bound their target, up from low single digits for earlier tools. Separately, an open coding model keeps its parent's benchmark scores while answering about 3x faster through speculative decoding with a code-tuned draft model.","title":"AI/ML","sources":[{"url":"https://example.org/fixture/protein-design","title":"Fixture source: protein design preprint"},{"url":"https://example.org/fixture/open-coder","title":"Fixture source: open coder model card"}],"section_id":"breakthroughs","methodology":"RFD4-Proteina: a diffusion generator refines noise into a backbone shaped to the target; flow-matching training gives a smoother path in fewer steps; structure and sequence are designed jointly. Tested on targets with good structural data; in-vitro binding only. Open coder: a small draft model proposes several tokens, the large model verifies them in one pass and keeps the correct prefix, so output is unchanged; the draft is trained on the large model's own code, raising acceptance. Gains shrink for prose and for large batches."},{"body":"Indexes closed lower: Nasdaq -1.2%, S&P 500 -0.8%, Dow -0.5%. A hotter-than-expected jobs report pushed bond yields up.","title":"Markets","sources":[{"url":"https://example.org/fixture/markets","title":"Fixture source: market close"}],"section_id":"markets"}]},"brief_version":1,"guide_version":"0.4"},"audio":{"2026-10-22/tldr-glance.mp3":"https://example.supabase.co/storage/v1/object/sign/x?token=t"},"preview_snapshot":null}
        """#
        let r = try JSONDecoder().decode(EditionResponse.self, from: Data(json.utf8))
        let path = try XCTUnwrap(r.bundle.cards.last?.glance?.audioPath)
        XCTAssertEqual(r.audio?[path], "https://example.supabase.co/storage/v1/object/sign/x?token=t")
    }
}
